// !!!! Note: If we modify "Pictures" here with "DoliDroid", then when
// selecting a file qualified for camera input (like the user photo),
// the selector to choose camera is not enabled.

// store in public directory for sharing. Associate with getExternalStorageDirectory+DIRECTORY_DOWNLOADS or getExternalPublicStorageDirectory(DIRECTORY_DOWNLOADS)
// file path will be storage/emulated/0/The Path/
// Use not recommended by Google.
// Not used by DoliDroid that use now getExternalFilesDir() with DIRECTORY_DOWNLOAD or DIRECTORY_PICTURES
//

// store in Android app package name directory. Associate with getExternalFilesDir
// file path will be storage/emulated/0/Android/data/com.example.ex/files/The Path/
// Removed when app is uninstalled

// Used by DoliDroid to store/read files generated by onShowFileChooser


// store in app root directory. Cannot access without root. Associate with getFilesDir
// file path will be storage/data/user/0/Android/data/com.example.ex/files/ThePath/
// not visible from a file explorer or USB access from desktop.
// Removed when app is uninstalled
// Used for clear config file dolidroid_prefs getApplicationContext().getFilesDir()+"/dolidroid_pref"
// Used also to store crypted file getApplicationContext().getFilesDir()+"/../shared_prefs/secret_shared_prefs.xml"
